semio-s-artifact-stdio-json = { workspace = true }
semio-s-artifact-stdio-md = { workspace = true }
semio-s-artifact-stdio-semio = { workspace = true }
geometry = { path = "../../../../../🧰️framework/🔨️modules/📐️geometry/📦️packages/🦀️rust", package = "semio-framework-geometry" }
# 🚚 Wave MATHEND (ticket 26/08/12/DISSOLVE-KERNELS-AND-MODULES-INTO-EVENT-SOURCED-ARTIFACTS): `crate::number`
# relocated out of `🧮️math` into its own framework module (domain-neutral exact-numeric vocabulary, exempt
# under the binding user ruling) — `🌱roots`/`📈️polynomial-internals`/`🌿️cas-internals`/the artifact snapshot
# now read `number::` directly. Wave FIXALG (same ticket) also moved `➕️algebra-internals`'s generic
# `VecG`/`MatG` into this same crate's own `algebra` module, fixing `🌿️cas-internals`'s two
# `math::algebra::MatG`/`math::algebra::VecG` call sites (`E0433: cannot find algebra in math` — wave M3d
# had moved `algebra` out of `semio_framework_math` into `📸️remodel` believing that plugin was its sole
# consumer, not knowing this wave's own migration of `cas`/`polynomial` had just created a second one here)
# to `number::MatG`/`number::VecG`. `semio-framework-math` (aliased `math`, kept solely for that broken
# `math::algebra::` path) is no longer a dependency of this crate — nothing else in it ever read `math::`.
semio-framework-number = { workspace = true }
# 🧭️ `workspace = true` only works when this crate's local dependency KEY matches the key in root
# `[workspace.dependencies]` verbatim — Cargo resolves workspace inheritance by that key, and a `package =`
# override does NOT redirect the lookup (verified empirically: `cargo check` errors
# "dependency.dsl was not found in workspace.dependencies" when trying `dsl = { workspace = true, package =
# "semio-framework-os-kernel-dsl" }`). So the renamed internal aliases below stay plain `path`+`package`
# deps; only the four whose local name already equals the workspace key use `workspace = true`.
semio-framework = { workspace = true }
semio-framework-plugin = { workspace = true }
semio-framework-dispatch-macros = { path = "../../../../../🧰️framework/🔨️modules/🔀️dispatch/📦️packages/🦀️rust", package = "semio-framework-dispatch-macros" }
semio-framework-schema = { path = "../../../../../🧰️framework/🔨️modules/🧬️schema/📦️packages/🦀️rust", package = "semio-framework-schema" }
pack = { path = "../../../../../🧰️framework/🔨️modules/🎒️pack/📦️packages/🦀️rust", package = "semio-framework-pack" }

[dev-dependencies]
semio-framework-plugin = { workspace = true, features = ["artifact-app-testing"] }
serde.workspace = true
serde_json.workspace = true
semio-framework-ui-scene = { path = "../../../../../🧰️framework/🔨️modules/🖱️ui/🎬️scene/📦️packages/🦀️rust" }
semio-framework-async-macros = { path = "../../../../../🧰️framework/🔨️modules/⏳️async/✨️macros/📦️packages/🦀️rust" }
semio-framework-os-spr = { path = "../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/📡️spr/📦️packages/🦀️rust" }

